#!/usr/bin/env bash
# sync-upstream.sh — vendor a third-party skill repo at a PINNED TAG and
# regenerate namespaced copies into skills/.
#
# The registry has two lanes:
#   AUTHORED  — our skills. Staged to the vault inbox, published by publish-skill.sh.
#   VENDORED  — someone else's skills. Pinned to an upstream tag, regenerated by
#               THIS script. Never hand-edited; local edits are overwritten.
#
# Usage:
#   sync-upstream.sh [options] <vendor-name>
#
# Options:
#   --tag <tag>    target upstream tag (default: the pin in .upstream.json)
#   --latest       resolve the newest semver tag from the remote and use it
#   --check        report drift and exit; write nothing
#   -y, --yes      skip the confirmation prompt
#   --list         list vendored upstreams and their pins
#
# Examples:
#   sync-upstream.sh --check mattpocock-skills      # what would change?
#   sync-upstream.sh --latest mattpocock-skills     # bump to newest release
#   sync-upstream.sh --tag v1.3.0 mattpocock-skills # bump to a specific release
#
# Compatible with macOS /bin/bash 3.2. No associative arrays, no mapfile.
set -euo pipefail

BIN_DIR="$(cd "$(dirname "$0")" && pwd)"
REGISTRY="$(cd "$BIN_DIR/.." && pwd)"
VENDOR_ROOT="$REGISTRY/vendor"
SKILLS="$REGISTRY/skills"

TAG=""; LATEST=0; CHECK=0; YES=0; NAME=""
usage() { sed -n '2,26p' "$0"; exit 1; }

while [ $# -gt 0 ]; do
  case "$1" in
    --tag) shift; TAG="${1:-}" ;;
    --latest) LATEST=1 ;;
    --check) CHECK=1 ;;
    -y|--yes) YES=1 ;;
    --list)
      for d in "$VENDOR_ROOT"/*/; do
        [ -f "$d/.upstream.json" ] || continue
        python3 - "$d/.upstream.json" <<'PY'
import json,sys
m=json.load(open(sys.argv[1]))
print("%-24s %-10s %s  (%s)" % (m["name"], m["tag"], m["commit"][:12], m.get("commit_date","?")))
PY
      done; exit 0 ;;
    -h|--help) usage ;;
    -*) echo "unknown option: $1" >&2; usage ;;
    *) NAME="$1" ;;
  esac
  shift
done

[ -n "$NAME" ] || usage
VDIR="$VENDOR_ROOT/$NAME"
META="$VDIR/.upstream.json"
[ -f "$META" ] || { echo "FATAL: no vendored upstream at $VDIR" >&2; exit 1; }

REPO=$(python3 -c "import json;print(json.load(open('$META'))['repo'])")
PREFIX=$(python3 -c "import json;print(json.load(open('$META'))['namespace_prefix'])")
CUR_TAG=$(python3 -c "import json;print(json.load(open('$META'))['tag'])")
CUR_SHA=$(python3 -c "import json;print(json.load(open('$META'))['commit'])")

WORK=$(mktemp -d); trap 'rm -rf "$WORK"' EXIT
echo "==> fetching $REPO"
git clone --quiet "$REPO" "$WORK/up"
cd "$WORK/up"

if [ "$LATEST" -eq 1 ]; then
  TAG=$(git tag --sort=-v:refname | grep -E '^v[0-9]+\.[0-9]+\.[0-9]+$' | head -1)
  [ -n "$TAG" ] || { echo "FATAL: no semver tags on remote" >&2; exit 1; }
fi
[ -n "$TAG" ] || TAG="$CUR_TAG"

git rev-parse -q --verify "refs/tags/$TAG" >/dev/null \
  || { echo "FATAL: tag '$TAG' not found upstream" >&2; exit 1; }
git checkout --quiet "$TAG"
NEW_SHA=$(git rev-parse HEAD)
NEW_DATE=$(git log -1 --format=%ad --date=short)

echo "    current pin : $CUR_TAG  ${CUR_SHA:0:12}"
echo "    target      : $TAG  ${NEW_SHA:0:12}  ($NEW_DATE)"

if [ "$CUR_SHA" = "$NEW_SHA" ]; then
  echo "==> already at $TAG — nothing to fetch."
  [ "$CHECK" -eq 1 ] && exit 0
else
  echo
  echo "==> upstream commits $CUR_TAG..$TAG"
  git log --oneline "$CUR_SHA..$NEW_SHA" 2>/dev/null | sed 's/^/    /' | head -40 || \
    echo "    (histories unrelated — review CHANGELOG.md by hand)"
  if [ -f CHANGELOG.md ]; then
    echo
    echo "==> CHANGELOG head"
    sed -n '1,40p' CHANGELOG.md | sed 's/^/    /'
  fi
fi

# --- what would change in skills/ -------------------------------------------
echo
echo "==> skill-set delta"
NEW_LIST="$WORK/new.txt"; OLD_LIST="$WORK/old.txt"
find "$WORK/up/skills" -name SKILL.md | sed "s#^$WORK/up/skills/##;s#/SKILL.md\$##" \
  | awk -F/ '{print $NF}' | sort -u > "$NEW_LIST"
ls "$SKILLS" 2>/dev/null | grep "^$PREFIX" | sed "s/^$PREFIX//" | sort -u > "$OLD_LIST" || true
ADDED=$(comm -13 "$OLD_LIST" "$NEW_LIST" | tr '\n' ' ')
REMOVED=$(comm -23 "$OLD_LIST" "$NEW_LIST" | tr '\n' ' ')
echo "    added   : ${ADDED:-(none)}"
echo "    removed : ${REMOVED:-(none)}"
echo "    total   : $(wc -l < "$NEW_LIST" | tr -d ' ') skills upstream"

if [ "$CHECK" -eq 1 ]; then
  echo
  echo "==> --check: nothing written."
  exit 0
fi

if [ "$YES" -eq 0 ]; then
  printf "\nProceed? regenerates %s%s* from %s [y/N] " "$PREFIX" "" "$TAG"
  read -r ans </dev/tty || ans=n
  case "$ans" in y|Y|yes|YES) ;; *) echo "aborted."; exit 1 ;; esac
fi

# --- refresh the pristine payload -------------------------------------------
echo
echo "==> refreshing $VDIR/src"
rm -rf "$VDIR/src"; cp -R "$WORK/up/skills" "$VDIR/src"
for f in LICENSE README.md CHANGELOG.md CONTEXT.md AGENTS.md; do
  [ -f "$WORK/up/$f" ] && cp "$WORK/up/$f" "$VDIR/$f" || true
done
[ -f "$WORK/up/.claude-plugin/plugin.json" ] && {
  mkdir -p "$VDIR/.claude-plugin"
  cp "$WORK/up/.claude-plugin/plugin.json" "$VDIR/.claude-plugin/plugin.json"; }
find "$VDIR" -name '.DS_Store' -delete 2>/dev/null || true

# --- regenerate namespaced skills -------------------------------------------
echo "==> regenerating skills/$PREFIX*"
# drop previously generated copies so removals upstream propagate
find "$SKILLS" -maxdepth 1 -type d -name "$PREFIX*" -exec rm -rf {} + 2>/dev/null || true

REPO="$REPO" TAG="$TAG" NEW_SHA="$NEW_SHA" NEW_DATE="$NEW_DATE" \
PREFIX="$PREFIX" VDIR="$VDIR" SKILLS="$SKILLS" NAME="$NAME" \
python3 "$BIN_DIR/lib/vendor_generate.py"

# --- record the new pin ------------------------------------------------------
python3 - "$META" "$TAG" "$NEW_SHA" "$NEW_DATE" <<'PY'
import json,sys,datetime
p,tag,sha,cdate=sys.argv[1:5]
m=json.load(open(p))
m["tag"]=tag; m["commit"]=sha; m["commit_date"]=cdate
m["vendored_at"]=datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
json.dump(m,open(p,"w"),indent=2); open(p,"a").write("\n")
PY

echo
echo "==> done. pinned at $TAG (${NEW_SHA:0:12})"
echo "    review:  git -C $REGISTRY status"
echo "    harness: $REGISTRY/sync-skills.sh"
